/bin/bash -c "python3 - <<'PY'
from pypdf import PdfReader
r=PdfReader('manuscript.pdf')
uris=set()
for p in r.pages:
 for a in p.get('/Annots',[]):
  obj=a.get_object()
  act=obj.get('/A')
  if act:
   u=act.get('/URI')
   if u: uris.add(str(u))
print('\\n'.join(sorted(uris)))
PY"
